{
  const { toBits, wait, raf, mkBit, mkRow, animateBit, animateAdd, mkInputRow, centerWidget } = slUtils;
  let bitsVal = 116;
  let maskVal = 21;

  function getInvalidBits(b, m) {
    const runLsb = b & ~((b &lt;&lt; 1) & 0xFF);
    const runMsb = b & ~((b &gt;&gt; 1) & 0xFF);
    const validMaskBits = (b - runLsb) | ((runMsb &lt;&lt; 1) & 0xFF) | ((runLsb &gt;&gt; 1) & 0xFF);
    return m & validMaskBits;
  }

  const prev = document._sl2State || {res: [0,0,0,0,0,0,0,0]};
  const prevR3Bits = prev.r3Bits || toBits(maskVal);
  const prevR3Labels = prev.r3Labels || false;

  const container = html`&lt;div style="
    font-family: var(--bs-font-monospace, monospace);
    font-size: 1.15rem;
    --sl-label-width: 5rem;
  "&gt;&lt;/div&gt;`;
  centerWidget(container);

  // MSB / LSB descriptor row — aligned with bitstring columns
  const descRow = document.createElement('div');
  descRow.style.cssText = 'display: flex; align-items: center; height: 1.2rem;';
  const descSpacer = document.createElement('div');
  descSpacer.style.cssText = 'width: calc(var(--sl-label-width, 5rem) + 1.6rem); flex-shrink: 0;';
  descRow.appendChild(descSpacer);
  const descLabel = document.createElement('div');
  descLabel.style.cssText = 'width: calc(8 * 1.5rem); display: flex; align-items: center; opacity: 0.3; font-size: 0.55em; letter-spacing: 0.05em; padding: 0 0.15rem;';
  const descMsb = document.createElement('span');
  descMsb.textContent = 'MSB';
  const descLine = document.createElement('span');
  descLine.style.cssText = 'flex: 1; border-bottom: 1px solid currentColor; margin: 0 0.4em; opacity: 0.5;';
  const descLsb = document.createElement('span');
  descLsb.textContent = 'LSB';
  descLabel.append(descMsb, descLine, descLsb);
  descRow.appendChild(descLabel);

  // --- Input rows ---
  const bitsRow = mkInputRow('bits\u00a0=', bitsVal, {
    editable: true,
    toggle(i) { bitsVal ^= (1 &lt;&lt; (7 - i)); sync(); }
  });
  const maskRow = mkInputRow('mask\u00a0=', maskVal, {
    editable: false,
    op: '+',
    toggle(i) { maskVal ^= (1 &lt;&lt; (7 - i)); sync(); }
  });

  bitsRow.hexInput.addEventListener('input', () =&gt; {
    const text = bitsRow.hexInput.value.replace(/[^0-9a-fA-F]/g, '');
    if (text !== bitsRow.hexInput.value) bitsRow.hexInput.value = text;
    if (text.length === 2) {
      const parsed = parseInt(text, 16);
      if (!isNaN(parsed)) { bitsVal = parsed; sync(); }
    }
  });
  bitsRow.hexInput.addEventListener('blur', () =&gt; {
    bitsRow.hexInput.value = bitsVal.toString(16).padStart(2, '0');
  });

  // Initial validation highlight
  const initInv = getInvalidBits(bitsVal, maskVal);
  for (let i = 0; i &lt; 8; i++) {
    if ((initInv &gt;&gt; (7 - i)) & 1) maskRow.bitRuns[i].classList.add('invalid');
  }

  // --- Animation rows ---
  const hr1 = document.createElement('hr');
  hr1.className = 'sl-hr';

  // Animated row: sum → invert
  const r3 = (() =&gt; {
    const r = document.createElement('div');
    r.className = 'sl-row';
    const l = document.createElement('span');
    l.className = 'sl-label';
    r.appendChild(l);
    const o = document.createElement('span');
